1	package tui
2	
3	import (
4		"fmt"
5		"strings"
6		"time"
7	
8		"charm.land/lipgloss/v2"
9	
10		"github.com/tedkulp/drops/internal/model"
11		"github.com/tedkulp/drops/internal/render"
12	)
13	
14	// column is one Board column. It is DERIVED, never stored: CONTEXT.md's
15	// Ready and Blocked are properties of an open issue rather than statuses, so
16	// nothing can be put into a column — an issue arrives in one by its status and
17	// its blockers.
18	type column int
19	
20	const (
21		colReady column = iota
22		colBlocked
23		colInProgress
24		colClosed
25	)
26	
27	// columnCount is how many columns the board has, whatever the width shows.
28	const columnCount = 4
29	
30	var columnNames = [columnCount]string{"Ready", "Blocked", "In progress", "Closed"}
31	
32	// minColumnWidth is the narrowest a column is drawn. What does not fit at it
33	// is paged sideways rather than squeezed (#2, variant E): four columns in an
34	// 80-column terminal are slivers nobody can read a title in.
35	const minColumnWidth = 28
36	
37	// columnOf derives one issue's column, one branch per clause.
38	//
39	// in_progress is asked BEFORE the blocker count, and that order is the rule
40	// rather than a detail of it: started work that is stuck is still started, so
41	// a blocked in_progress issue sits in In progress and says `blocked by N` on
42	// its card instead of looking unstarted.
43	func columnOf(candidate row) column {
44		switch {
45		case candidate.status == model.StatusClosed:
46			return colClosed
47		case candidate.status == model.StatusInProgress:
48			return colInProgress
49		case candidate.blockedBy > 0:
50			return colBlocked
51		}
52		return colReady
53	}
54	
55	// boardCards sets the narrowed rows out in their columns.
56	//
57	// Ready, Blocked and In progress come from the list's own row set, in the
58	// CLI's order, and Closed comes from core's closed read, most recently closed
59	// first. Neither is re-sorted.
60	func (m *Model) boardCards() [columnCount][]row {
61		var cards [columnCount][]row
62		for _, candidate := range append(m.narrow(liveRows(m.all)), m.narrow(m.closed)...) {
63			cards[columnOf(candidate)] = append(cards[columnOf(candidate)], candidate)
64		}
65		return cards
66	}
67	
68	// liveRows is the list's rows without the closed ones `C` adds. Those arrive in
69	// the QUEUE's order, and the board's Closed column is core's order, so the
70	// board takes its closed cards from the closed read and never from here.
71	func liveRows(rows []row) []row {
72		live := make([]row, 0, len(rows))
73		for _, candidate := range rows {
74			if candidate.status == model.StatusClosed {
75				continue
76			}
77			live = append(live, candidate)
78		}
79		return live
80	}
81	
82	// shownColumns is how many columns fit a board this wide at minColumnWidth,
83	// separators included, and never fewer than one.
84	func shownColumns(boardWidth int) int {
85		return max(1, min(columnCount, (boardWidth+1)/(minColumnWidth+1)))
86	}
87	
88	// firstColumn is the leftmost column on screen once the focused column has
89	// been scrolled into view, from whichever side it went off.
90	func firstColumn(first, focused, shown int) int {
91		if focused < first {
92			first = focused
93		}
94		if focused >= first+shown {
95			first = focused - shown + 1
96		}
97		return max(0, min(first, columnCount-shown))
98	}
99	
100	// pageBoard keeps the focused column on screen at the current width. It
101	// measures the board as drawn unzoomed, because `enter`-zoom hides the board
102	// without changing what it will show when it comes back.
103	func (m *Model) pageBoard() {
104		m.first = firstColumn(m.first, int(m.focus), shownColumns(measureBoard(m.width, m.height).listWidth))
105	}
106	
107	// cardLines is how many lines a card takes, and cardsFit how many whole cards
108	// a column shows under its heading, a blank line between each.
109	const cardLines = 3
110	
111	func cardsFit(rows int) int { return max(rows/(cardLines+1), 1) }
112	
113	// cardTop is the first card a column shows so the selected one is on screen.
114	// It is derived from the selection rather than held, like the list's window.
115	func cardTop(selected, fit int) int { return max(0, selected-fit+1) }
116	
117	// switchColumn is `tab` and `shift+tab`: step one column, wrapping round all
118	// four, and land on the card at the same row position on screen, or the last
119	// card above it. The cursor moved, so the follow trail goes with it.
120	func (m *Model) switchColumn(step int) error {
121		fit := cardsFit(m.geo().rows)
122		offset := m.cursor.position - cardTop(m.cursor.position, fit)
123		m.focus = column((int(m.focus) + step + columnCount) % columnCount)
124		m.pageBoard()
125		m.clearFollow()
126		m.cursor.move(m.current(), offset)
127		return m.showDetail(m.cursor.id)
128	}
129	
130	// toggleBoard is `B`. It reads nothing: the board's rows are loaded with the
131	// list's, and everything that narrows or trails — the cursor's id, `/`, `a`,
132	// `r`, the follow stack — is the model's rather than a view's, so it is
133	// already there. The right pane is redrawn from the view it already holds at
134	// the new pane width.
135	//
136	// The one read `B` can cause is the list's own rule applying: a closed card
137	// is not a list row with `C` off, so going back puts the cursor on the row
138	// that held its place, and a different issue is a page read like any other.
139	//
140	// When the cursor does land on a different issue, that is the cursor moving,
141	// so the follow trail goes with it, as it does for every other cursor move.
142	func (m *Model) toggleBoard() error {
143		carried := m.cursor.id
144		m.board = !m.board
145		m.resize()
146		m.place()
147		if m.cursor.id != carried {
148			m.clearFollow()
149		}
150		target := m.cursor.id
151		if len(m.stack) > 0 {
152			target = m.detailID
153		}
154		if target != "" && target == m.detailID {
155			return m.display(target, m.detailView)
156		}
157		return m.showDetail(target)
158	}
159	
160	// age is how long ago a moment was, in the prototype's buckets: minutes under
161	// an hour, hours under two days, days under sixty, months under a year, then
162	// years.
163	func age(elapsed time.Duration) string {
164		const day = 24 * time.Hour
165		switch {
166		case elapsed < time.Hour:
167			return fmt.Sprintf("%dm", max(int(elapsed.Minutes()), 0))
168		case elapsed < 48*time.Hour:
169			return fmt.Sprintf("%dh", int(elapsed.Hours()))
170		case elapsed < 60*day:
171			return fmt.Sprintf("%dd", int(elapsed/day))
172		case elapsed < 365*day:
173			return fmt.Sprintf("%dmo", int(elapsed/(30*day)))
174		}
175		return fmt.Sprintf("%dy", int(elapsed/(365*day)))
176	}
177	
178	// since is the moment a card's age counts from, which depends on the column:
179	// how long it has waited (Ready, Blocked), been under way (In progress), or
180	// been finished (Closed). A moment the issue lacks falls back to its creation.
181	func since(candidate row, col column) *model.Timestamp {
182		moment := candidate.created
183		switch col {
184		case colInProgress:
185			moment = candidate.started
186		case colClosed:
187			moment = candidate.closedAt
188		}
189		if moment == nil {
190			return candidate.created
191		}
192		return moment
193	}
194	
195	// card is one card's three lines, unstyled, none wider than width.
196	//
197	//  1. the status mark, priority, type and id, with the age flush right;
198	//  2. the title;
199	//  3. whichever of `@assignee` and `blocked by N` are present.
200	//
201	// Geometry lives here rather than in render, like the list's row, and the
202	// primitives are render's.
203	func card(candidate row, col column, width int, now time.Time) [cardLines]string {
204		head := fmt.Sprintf("%s P%d %s %s", render.StatusMark(candidate.status, candidate.tombstoned),
205			candidate.priority, candidate.kind, candidate.id)
206		when := ""
207		if moment := since(candidate, col); moment != nil {
208			if at, err := moment.Time(); err == nil {
209				when = age(now.Sub(at))
210			}
211		}
212	
213		var facts []string
214		if candidate.assignee != "" {
215			facts = append(facts, "@"+candidate.assignee)
216		}
217		if candidate.blockedBy > 0 {
218			facts = append(facts, fmt.Sprintf("blocked by %d", candidate.blockedBy))
219		}
220		return [cardLines]string{
221			flush(head, when, width),
222			render.Ellipsis(candidate.title, width),
223			render.Ellipsis(strings.Join(facts, " · "), width),
224		}
225	}
226	
227	// flush puts right against the right edge and cuts left to what is left.
228	func flush(left, right string, width int) string {
229		if right == "" {
230			return render.Ellipsis(left, width)
231		}
232		room := width - render.Cols(right) - 1
233		if room < 1 {
234			return render.Ellipsis(right, width)
235		}
236		left = render.Ellipsis(left, room)
237		return left + strings.Repeat(" ", room-render.Cols(left)) + " " + right
238	}
239	
240	// heading is a column's name and count. `▸ ` marks the focused column and
241	// only that one; the others get two spaces, so names line up either way.
242	func heading(col column, count int, focused bool) string {
243		marker := "  "
244		if focused {
245			marker = "▸ "
246		}
247		return fmt.Sprintf("%s%s %d", marker, columnNames[col], count)
248	}
249	
250	// columnBody renders one column into exactly width × height. selected is the
251	// cursor's card, or -1 in a column that is not focused.
252	func columnBody(col column, cards []row, selected, width, height int, now time.Time) string {
253		focused := selected >= 0
254		title := render.Ellipsis(heading(col, len(cards), focused), width)
255		if focused {
256			title = headStyle.Render(title)
257		} else {
258			title = dimStyle.Render(title)
259		}
260		lines := []string{title}
261	
262		fit := cardsFit(height)
263		top := cardTop(max(selected, 0), fit)
264		for index := top; index < len(cards) && index < top+fit; index++ {
265			if index > top {
266				lines = append(lines, "")
267			}
268			for _, line := range card(cards[index], col, width, now) {
269				// Padded before styling, so reverse video covers the card's
270				// whole width rather than stopping at its text.
271				line += strings.Repeat(" ", max(0, width-lipgloss.Width(line)))
272				switch {
273				case focused && index == selected:
274					line = cursorStyle.Render(line)
275				case cards[index].status == model.StatusClosed:
276					line = dimStyle.Render(line)
277				}
278				lines = append(lines, line)
279			}
280		}
281		return pad(strings.Join(lines, "\n"), width, height)
282	}
283	
284	// boardBody is the columns on screen, side by side with a dim `│` between,
285	// exactly width × height. The last column takes what integer division left.
286	//
287	// The columns start at m.first, which pageBoard keeps current on every focus
288	// change and resize, so drawing reads it rather than moving it.
289	func (m *Model) boardBody(width, height int) string {
290		shown := shownColumns(width)
291		columnWidth := max((width-(shown-1))/shown, 1)
292		now := m.now()
293	
294		blocks := make([][]string, 0, shown)
295		for index := m.first; index < m.first+shown; index++ {
296			col := column(index)
297			span := columnWidth
298			if index == m.first+shown-1 {
299				span = max(width-(shown-1)-(shown-1)*columnWidth, 1)
300			}
301			selected := -1
302			if col == m.focus {
303				selected = m.cursor.position
304			}
305			blocks = append(blocks, strings.Split(columnBody(col, m.cards[col], selected, span, height, now), "\n"))
306		}
307	
308		separator := dimStyle.Render("│")
309		lines := make([]string, 0, height)
310		for line := range height {
311			parts := make([]string, 0, len(blocks))
312			for _, block := range blocks {
313				parts = append(parts, block[line])
314			}
315			lines = append(lines, strings.Join(parts, separator))
316		}
317		return pad(strings.Join(lines, "\n"), width, height)
318	}
319	
320	// boardTitle names the scope, and says how many columns are off screen on
321	// each side while any are.
322	func (m *Model) boardTitle(width int) string {
323		title := m.listTitle()
324		shown := shownColumns(width)
325		if shown < columnCount {
326			title += fmt.Sprintf(" · ◀ %d · %d ▶", m.first, columnCount-m.first-shown)
327		}
328		return title
329	}
330	
331	// boardCount is how many cards the board shows.
332	func (m *Model) boardCount() int {
333		total := 0
334		for _, cards := range m.cards {
335			total += len(cards)
336		}
337		return total
338	}
339	
340	// boardLoaded is how many cards the board would show with nothing narrowing:
341	// the live rows and core's closed rows, each once.
342	func (m *Model) boardLoaded() int { return len(liveRows(m.all)) + len(m.closed) }
