// is why `r` is a narrowing and not a scope change.
//
// One function rather than the expression written twice, because applyFilter
// and refresh both need it and they must never disagree about what is on
// screen.
func (m *Model) visible() []row { return m.narrow(m.all) }

// narrow is visible over any loaded rows, so the board's columns are cut by
// exactly the predicate and the substring the list is.
func (m *Model) narrow(rows []row) []row {
	if m.readyOnly {
		rows = ready(rows)
	}
	return matching(rows, m.filter)
}

// derive re-narrows both views from what is loaded and puts the cursor back
// on whichever is up.
func (m *Model) derive() {
	m.rows = m.visible()
	m.cards = m.boardCards()
	m.place()
}

// current is the rows the cursor moves over: the list, or the focused column.
func (m *Model) current() []row {
	if m.board {
		return m.cards[m.focus]
	}
	return m.rows
}

// place restores the cursor onto the view that is up. On the board the
// cursor's issue can be in any column, so the column holding it takes the
// focus first and the cursor rides its id there; the position is only the
// fallback, exactly as it is in the list.
func (m *Model) place() {
	if m.board {
		for index, cards := range m.cards {
			if m.cursor.id != "" && slices.ContainsFunc(cards, func(candidate row) bool { return candidate.id == m.cursor.id }) {
				m.focus = column(index)
				break
			}
		}
		m.pageBoard()
	}
	m.cursor.restore(m.current())
}

// applyFilter narrows the loaded set and restores the cursor onto it.
func (m *Model) applyFilter() error {
	m.clearFollow()
	m.derive()
	return m.showDetail(m.cursor.id)
}

// refresh re-reads the row set after a WRITE, which is a different motion from
func (m *Model) compose() string {
	geo := m.geo()
	rows := m.detailRows(geo)
	m.detail.SetWidth(geo.detailWidth)
	m.detail.SetHeight(rows)

	if m.help {
		return pad(helpText(), m.width, m.height)
	}

	// The picker takes the detail pane's BODY, keeping qy3de.5's box and its
	// border title. A centred overlay needs lipgloss layer compositing that
	// nothing here has built or measured; replacing the body reuses pad/box
	// geometry already proved off-width-zero. Under `enter`-zoom the body is
	// the full width and the picker follows it there.
	inner := pad(m.detail.View(), geo.detailWidth, rows)
	if m.modal != nil {
		inner = m.modal.view(geo.detailWidth, rows)
	}
	if line := m.depthLine(geo.detailWidth); line != "" {
		inner = line + "\n" + inner
	}
	detail := box(pad(inner, geo.detailWidth, geo.rows), geo.detailWidth, m.detailTitle())
	body := detail
	switch {
	case m.zoomed:
	case m.board:
		body = lipgloss.JoinHorizontal(lipgloss.Top,
			box(m.boardBody(geo.listWidth, geo.rows), geo.listWidth, m.boardTitle(geo.listWidth)), detail)
	default:
		list := listBody(m.rows, m.cursor.position, geo.listWidth, geo.rows,
			m.scope.allProjects, m.emptyState())
		body = lipgloss.JoinHorizontal(lipgloss.Top,
			box(list, geo.listWidth, m.listTitle()), detail)
	}
	if m.messageLines() > 0 {
		body += "\n" + pad(headStyle.Render(render.Ellipsis(m.statusLine(), m.width)), m.width, 1)
	}
	return body + "\n" + m.footer(geo)
}

// listTitle names the scope the left pane is showing.
func (m *Model) listTitle() string {
	if m.scope.allProjects {
		return "all projects"
	}
	return m.source.project.Slug
}

// detailTitle is the FULL untruncated id. It is the whole justification for
// the left pane's 12-column id cap: the row truncates what identifies, and
// this is where it is recovered.
func (m *Model) detailTitle() string { return string(m.detailID) }

// emptyState names the narrowing that emptied the pane. Collapsing the cases
// makes an empty project look like a bad filter or a fully blocked project.
func (m *Model) emptyState() string {
	if m.filter != "" {
