}

// The clause: `▸` marks the focused column's heading and no other.
func TestOnlyTheFocusedColumnIsMarked(t *testing.T) {
	fixture := newFixture(t)
	fixture.issue("an issue", 2)
	pane := onBoard(t, fixture, 200, 30)
